WITH RECURSIVE anc(c) AS (SELECT pre_code FROM kg_edge WHERE point_code = :code AND subject_id = CAST(:subject_id AS INTEGER) UNION SELECT e.pre_code FROM kg_edge e JOIN anc ON e.point_code = anc.c WHERE e.subject_id = CAST(:subject_id AS INTEGER)) SELECT p.code AS code, p.title AS title FROM kg_point p WHERE p.code IN (SELECT c FROM anc) AND p.code <> :code AND p.subject_id = CAST(:subject_id AS INTEGER) ORDER BY p.id
